/**
 * Pure entity-resolution helpers for the Runway Gantt pipeline.
 *
 * These are the testable, DB-free exports extracted from
 * scripts/lib/gantt/resolve-entity.ts. The async DB-coupled wrappers
 * (resolveProject, resolveClient) remain in scripts/lib/gantt/resolve-entity.ts
 * and import these helpers via a relative path back into src/.
 */

import { fuzzyMatch } from "@/lib/runway/operations-utils";
import type {
  ClientRow,
  ProjectRow,
  ResolvedSubject,
} from "./types";

// ── Pure helpers (testable without DB) ────────────────────

export function classifyProject(
  project: ProjectRow,
  childProjects: ProjectRow[],
): ResolvedSubject {
  const isWrapper =
    project.parentProjectId === null &&
    project.engagementType === "retainer" &&
    childProjects.length > 0;
  return isWrapper
    ? { kind: "wrapper", project, childProjects }
    : { kind: "l1", project };
}

function displayLabel(project: ProjectRow, clientsById: Map<string, ClientRow>): string {
  const clientName = clientsById.get(project.clientId)?.name ?? "?";
  // Include project id so an ambiguous user can copy-paste an exact match
  // back into `--project <id>`.
  return `${clientName}: ${project.name} (id=${project.id})`;
}

function parseNicknames(raw: string | null): string[] {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((s): s is string => typeof s === "string") : [];
  } catch {
    return [];
  }
}

/**
 * Build the qualified-match keys for a project. Used after the plain-name
 * fuzzy pass fails. Lets users type "hdl Website Build", "Convergix CDS",
 * or "Convergix / CDS Messaging" and reach the right project. Each
 * client-prefix is emitted in both " / " and bare-space forms so the user
 * doesn't have to think about the separator.
 */
function projectQualifiedKeys(
  project: ProjectRow,
  clientsById: Map<string, ClientRow>,
): string[] {
  const client = clientsById.get(project.clientId);
  if (!client) return [];
  const prefixes = [client.name, client.slug, ...parseNicknames(client.nicknames)];
  const keys: string[] = [];
  for (const prefix of prefixes) {
    keys.push(`${prefix} / ${project.name}`);
    keys.push(`${prefix} ${project.name}`);
  }
  return keys;
}

export function resolveProjectFromList(
  projectList: ProjectRow[],
  clientsById: Map<string, ClientRow>,
  input: string,
):
  | { ok: true; project: ProjectRow }
  | { ok: false; error: string; available?: string[] } {
  // 1. Exact id match
  const idHit = projectList.find((p) => p.id === input);
  if (idHit) return { ok: true, project: idHit };

  // 2. Fuzzy match on plain name
  const nameResult = fuzzyMatch(projectList, input, (p) => p.name);
  if (nameResult.kind === "match") return { ok: true, project: nameResult.value };

  // 3. Fuzzy match across all qualified keys (name, slug, nicknames). One
  //    project may contribute several entries; collapse duplicates by id.
  type Entry = { key: string; project: ProjectRow };
  const entries: Entry[] = projectList.flatMap((p) =>
    projectQualifiedKeys(p, clientsById).map((key) => ({ key, project: p })),
  );
  const qualifiedResult = fuzzyMatch(entries, input, (e) => e.key);

  if (qualifiedResult.kind === "match") {
    return { ok: true, project: qualifiedResult.value.project };
  }
  if (qualifiedResult.kind === "ambiguous") {
    const uniqueProjects = Array.from(
      new Map(qualifiedResult.options.map((e) => [e.project.id, e.project])).values(),
    );
    if (uniqueProjects.length === 1) {
      return { ok: true, project: uniqueProjects[0] };
    }
  }

  // 4. Ambiguous on either side → return options (deduped)
  if (nameResult.kind === "ambiguous" || qualifiedResult.kind === "ambiguous") {
    const options =
      nameResult.kind === "ambiguous"
        ? nameResult.options
        : qualifiedResult.kind === "ambiguous"
          ? Array.from(
              new Map(qualifiedResult.options.map((e) => [e.project.id, e.project])).values(),
            )
          : [];
    const display = options.map((p) => displayLabel(p, clientsById));
    return {
      ok: false,
      error: `Multiple projects match '${input}'. Use --project <id> or a more specific name. Candidates:`,
      available: display,
    };
  }

  return {
    ok: false,
    error: `Project '${input}' not found.`,
    available: projectList.map((p) => displayLabel(p, clientsById)),
  };
}

export function resolveClientFromList(
  clientList: ClientRow[],
  input: string,
):
  | { ok: true; client: ClientRow }
  | { ok: false; error: string; available?: string[] } {
  // 1. Exact id
  const idHit = clientList.find((c) => c.id === input);
  if (idHit) return { ok: true, client: idHit };
  // 2. Exact slug (case-insensitive)
  const slugHit = clientList.find((c) => c.slug.toLowerCase() === input.toLowerCase());
  if (slugHit) return { ok: true, client: slugHit };
  // 3. Fuzzy on name
  const result = fuzzyMatch(clientList, input, (c) => c.name);
  if (result.kind === "match") return { ok: true, client: result.value };
  if (result.kind === "ambiguous") {
    const options = result.options.map((c) => `${c.name} (slug=${c.slug})`);
    return {
      ok: false,
      error: `Multiple clients match '${input}'. Use --client <slug> or a more specific name. Candidates:`,
      available: options,
    };
  }
  return {
    ok: false,
    error: `Client '${input}' not found.`,
    available: clientList.map((c) => c.name),
  };
}

/**
 * Pure RawData assembly for the Runway Gantt pipeline.
 *
 * This is the testable, DB-free export extracted from
 * scripts/lib/gantt/extract-data.ts. The async DB-coupled wrapper
 * (extractData) remains in scripts/lib/gantt/extract-data.ts and imports
 * buildRawData via a relative path back into src/.
 */

import type {
  ClientRow,
  RawData,
  ResolvedSubject,
  WeekItemRow,
} from "./types";

/**
 * Pure: assemble RawData from already-fetched inputs. The same fetched
 * `weekItemsForEntity` is treated as orphans for a wrapper subject and as
 * the rendered child rows for an L1 subject.
 */
export function buildRawData(
  subject: ResolvedSubject,
  client: ClientRow,
  weekItemsForEntity: WeekItemRow[],
): RawData {
  if (subject.kind === "wrapper") {
    return {
      kind: "wrapper",
      entity: subject.project,
      client,
      children: subject.childProjects,
      orphanWeekItems: weekItemsForEntity.map((w) => ({ id: w.id, title: w.title })),
    };
  }
  return {
    kind: "l1",
    entity: subject.project,
    client,
    children: weekItemsForEntity,
  };
}

/**
 * Pure section-builder helpers for the Runway Gantt rundown pipeline.
 *
 * These are the testable, DB-free exports extracted from
 * scripts/lib/gantt/rundown.ts. The async DB-coupled wrapper
 * (extractClientRundown) remains in scripts/lib/gantt/rundown.ts and imports
 * these helpers via a relative path back into src/.
 */

import {
  detectL1Issues,
  detectWeekItemIssues,
  detectWrapperIssues,
} from "./detect-issues";
import { computeAxis, formatDateRange, transformRows } from "./transform-rows";
import { summarize } from "./counter";
import type {
  AnnotatedRow,
  ClientRow,
  GanttData,
  GanttRow,
  Issue,
  ProjectRow,
  RawData,
  SeverityCounts,
  WeekItemRow,
} from "./types";

/**
 * Build a single-section GanttData for a project entity. Used both for
 * standalone L1s and for drilling into a wrapper-child. `extraChartIssues`
 * lets the wrapper-child path append its relational issues (parent-date
 * mismatch etc.) on the child's own section instead of the rollup.
 */
export function buildL1SectionData(
  entity: ProjectRow,
  client: ClientRow,
  weekItemsForEntity: WeekItemRow[],
  todayISO: string,
  generatedAt: string,
  extraChartIssues: Issue[] = [],
): GanttData {
  const raw: RawData = { kind: "l1", entity, client, children: weekItemsForEntity };
  const rows = transformRows(raw);
  const axis = computeAxis(raw, rows, new Date(`${todayISO}T00:00:00Z`));
  const itemById = new Map(weekItemsForEntity.map((w) => [w.id, w]));
  const annotated: AnnotatedRow[] = rows.map((row) => {
    if (row.kind !== "weekitem") return { ...row, inline: [], subRow: [] };
    const item = itemById.get(row.id);
    if (!item) return { ...row, inline: [], subRow: [] };
    return { ...row, ...detectWeekItemIssues(item, entity, todayISO) };
  });
  const chartIssues = [
    ...detectL1Issues(entity, weekItemsForEntity.length),
    ...extraChartIssues,
  ];
  const headerRange = formatDateRange(entity.startDate, entity.endDate);
  return {
    raw,
    rows: annotated,
    chartIssues,
    axis,
    headerRange,
    generatedAt,
    summary: summarize({ rows: annotated, chartIssues, entity }),
  };
}

/**
 * Wrapper rollup section — chart issues are wrapper-level only. Rows show
 * the children L1s as visual Gantt rows but with NO per-row inline or
 * sub-row alerts (those move to each child's drill-in section).
 */
export function buildWrapperSectionData(
  wrapper: ProjectRow,
  client: ClientRow,
  childProjects: ProjectRow[],
  orphanWeekItems: { id: string; title: string }[],
  generatedAt: string,
  todayISO: string,
): GanttData {
  const raw: RawData = {
    kind: "wrapper",
    entity: wrapper,
    client,
    children: childProjects,
    orphanWeekItems,
  };
  const baseRows: GanttRow[] = transformRows(raw);
  const axis = computeAxis(raw, baseRows, new Date(`${todayISO}T00:00:00Z`));
  // Suppress per-row alerts on the rollup — operator-locked.
  const annotated: AnnotatedRow[] = baseRows.map((row) => ({
    ...row,
    inline: [],
    subRow: [],
  }));
  const chartIssues = detectWrapperIssues(wrapper, childProjects, orphanWeekItems);
  const headerRange = formatDateRange(wrapper.startDate, wrapper.endDate);
  return {
    raw,
    rows: annotated,
    chartIssues,
    axis,
    headerRange,
    generatedAt,
    summary: summarize({ rows: annotated, chartIssues, entity: wrapper }),
  };
}

export function slugAnchor(input: string): string {
  return input
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

export function addSeverity(target: SeverityCounts, src: SeverityCounts): void {
  target.critical += src.critical;
  target.warn += src.warn;
  target.info += src.info;
}

import { describe, expect, it } from "vitest";
import {
  classifyProject,
  resolveClientFromList,
  resolveProjectFromList,
} from "./resolve-helpers";
import type { ClientRow, ProjectRow } from "./types";

const NOW = new Date("2026-04-28T00:00:00Z");

function makeClient(overrides: Partial<ClientRow> = {}): ClientRow {
  return {
    id: "c-default",
    name: "Default Client",
    slug: "default-client",
    nicknames: null,
    contractValue: null,
    contractTerm: null,
    contractStatus: null,
    team: null,
    clientContacts: null,
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

function makeProject(overrides: Partial<ProjectRow> = {}): ProjectRow {
  return {
    id: "p-default",
    clientId: "c-default",
    name: "Default Project",
    status: null,
    category: null,
    owner: null,
    resources: null,
    waitingOn: null,
    dueDate: null,
    startDate: null,
    endDate: null,
    contractStart: null,
    contractEnd: null,
    engagementType: null,
    parentProjectId: null,
    notes: null,
    staleDays: null,
    sortOrder: 0,
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

describe("classifyProject", () => {
  const baseRetainer = makeProject({
    id: "wrapper",
    engagementType: "retainer",
    parentProjectId: null,
  });
  const child = makeProject({ id: "child", parentProjectId: "wrapper" });

  it("classifies retainer with children as wrapper", () => {
    const result = classifyProject(baseRetainer, [child]);
    expect(result.kind).toBe("wrapper");
    if (result.kind === "wrapper") {
      expect(result.childProjects).toHaveLength(1);
    }
  });

  it("treats retainer with no children as L1 (degenerate)", () => {
    const result = classifyProject(baseRetainer, []);
    expect(result.kind).toBe("l1");
  });

  it("treats non-retainer engagement as L1 even with children", () => {
    const project = makeProject({
      id: "px",
      engagementType: "project",
      parentProjectId: null,
    });
    const result = classifyProject(project, [child]);
    expect(result.kind).toBe("l1");
  });

  it("treats sub-project (parentProjectId set) as L1", () => {
    const subProject = makeProject({
      id: "sub",
      engagementType: "retainer",
      parentProjectId: "wrapper",
    });
    const result = classifyProject(subProject, []);
    expect(result.kind).toBe("l1");
  });

  it("treats null engagementType as L1", () => {
    const project = makeProject({ engagementType: null, parentProjectId: null });
    const result = classifyProject(project, [child]);
    expect(result.kind).toBe("l1");
  });
});

describe("resolveProjectFromList", () => {
  const ag1 = makeClient({ id: "c-ag1", name: "AG1", slug: "ag1" });
  const cgx = makeClient({ id: "c-cgx", name: "Convergix", slug: "convergix" });
  const clientsById = new Map([
    [ag1.id, ag1],
    [cgx.id, cgx],
  ]);

  const wrapper = makeProject({
    id: "p-ag1-wrap",
    clientId: ag1.id,
    name: "AG1",
    engagementType: "retainer",
  });
  const proContent = makeProject({
    id: "p-ag1-pro",
    clientId: ag1.id,
    name: "AG1 PRO Content",
    parentProjectId: wrapper.id,
  });
  const cdsMessaging = makeProject({
    id: "p-cgx-cds",
    clientId: cgx.id,
    name: "CDS Messaging",
  });

  const allProjects = [wrapper, proContent, cdsMessaging];

  it("matches by exact id", () => {
    const result = resolveProjectFromList(allProjects, clientsById, "p-cgx-cds");
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.project.id).toBe("p-cgx-cds");
  });

  it("matches by exact name", () => {
    const result = resolveProjectFromList(allProjects, clientsById, "CDS Messaging");
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.project.id).toBe("p-cgx-cds");
  });

  it("matches by qualified Client / Name", () => {
    const result = resolveProjectFromList(
      allProjects,
      clientsById,
      "Convergix / CDS Messaging",
    );
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.project.id).toBe("p-cgx-cds");
  });

  it("matches by client slug + project name", () => {
    // Mimics --project "hdl Website Build" — slug-qualified key
    const hdl = makeClient({ id: "c-hdl", name: "High Desert Law", slug: "hdl" });
    const websiteBuild = makeProject({
      id: "p-hdl-web",
      clientId: hdl.id,
      name: "Website Build",
    });
    const result = resolveProjectFromList(
      [websiteBuild],
      new Map([[hdl.id, hdl]]),
      "hdl Website Build",
    );
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.project.id).toBe("p-hdl-web");
  });

  it("matches by nickname + project name", () => {
    const cgxNick = makeClient({
      id: "c-cgx2",
      name: "1H Convergix",
      slug: "convergix-1h",
      nicknames: JSON.stringify(["CGX", "Convergix"]),
    });
    const retainer = makeProject({
      id: "p-cgx-ret",
      clientId: cgxNick.id,
      name: "1H Convergix Retainer",
      engagementType: "retainer",
    });
    const result = resolveProjectFromList(
      [retainer],
      new Map([[cgxNick.id, cgxNick]]),
      "CGX / 1H Convergix Retainer",
    );
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.project.id).toBe("p-cgx-ret");
  });

  it("collapses multiple key-hits for the same project to a single match", () => {
    // Input matches BOTH name-qualified and slug-qualified keys for one project;
    // the resolver should not treat this as ambiguous.
    const hdl = makeClient({ id: "c-hdl", name: "High Desert Law", slug: "hdl" });
    const websiteBuild = makeProject({
      id: "p-hdl-web",
      clientId: hdl.id,
      name: "Website Build",
    });
    const result = resolveProjectFromList(
      [websiteBuild],
      new Map([[hdl.id, hdl]]),
      "Website Build",
    );
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.project.id).toBe("p-hdl-web");
  });

  it("tolerates malformed nicknames JSON without throwing", () => {
    const broken = makeClient({
      id: "c-broken",
      name: "Broken",
      slug: "broken",
      nicknames: "{not-valid-json",
    });
    const project = makeProject({
      id: "p-broken",
      clientId: broken.id,
      name: "Project",
    });
    const result = resolveProjectFromList(
      [project],
      new Map([[broken.id, broken]]),
      "Project",
    );
    expect(result.ok).toBe(true);
  });

  it("returns disambiguation list when multiple names share a startsWith substring", () => {
    // No exact-name match on "AG1 P" — but two projects start with it.
    const social = makeProject({
      id: "p-ag1-social",
      clientId: ag1.id,
      name: "AG1 PRO Social Drafts",
    });
    const result = resolveProjectFromList(
      [...allProjects, social],
      clientsById,
      "AG1 P",
    );
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error).toMatch(/Multiple projects match 'AG1 P'/);
      expect(result.error).toContain("Use --project <id> or a more specific name");
      expect(result.available).toEqual(
        expect.arrayContaining(["AG1: AG1 PRO Content (id=p-ag1-pro)", "AG1: AG1 PRO Social Drafts (id=p-ag1-social)"]),
      );
    }
  });

  it("prefers exact-name match over substring even when other names share the substring", () => {
    // "AG1" exactly matches the wrapper despite other projects whose names contain "AG1".
    const social = makeProject({
      id: "p-ag1-social",
      clientId: ag1.id,
      name: "AG1 Social Drafts",
    });
    const result = resolveProjectFromList(
      [...allProjects, social],
      clientsById,
      "AG1",
    );
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.project.id).toBe("p-ag1-wrap");
  });

  it("returns not-found error with full list on no match", () => {
    const result = resolveProjectFromList(allProjects, clientsById, "Nope");
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error).toBe("Project 'Nope' not found.");
      expect(result.available).toContain("AG1: AG1 (id=p-ag1-wrap)");
    }
  });

  it("renders unknown clientId as '?' in disambiguation labels", () => {
    const orphan = makeProject({
      id: "p-orphan",
      clientId: "c-missing",
      name: "Orphan Project",
    });
    const result = resolveProjectFromList([orphan], clientsById, "Nope");
    expect(result.ok).toBe(false);
    if (!result.ok) expect(result.available).toContain("?: Orphan Project (id=p-orphan)");
  });
});

describe("resolveClientFromList", () => {
  const ag1 = makeClient({ id: "c-ag1", name: "AG1", slug: "ag1" });
  const cgx = makeClient({ id: "c-cgx", name: "Convergix", slug: "convergix" });
  const conv2 = makeClient({ id: "c-conv2", name: "Convergent Group", slug: "convergent-group" });
  const all = [ag1, cgx, conv2];

  it("matches by exact id", () => {
    const result = resolveClientFromList(all, "c-cgx");
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.client.id).toBe("c-cgx");
  });

  it("matches by exact slug (case-insensitive)", () => {
    const result = resolveClientFromList(all, "AG1");
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.client.id).toBe("c-ag1");
  });

  it("matches by fuzzy name when no slug or id hits", () => {
    const result = resolveClientFromList(all, "Convergix");
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.client.id).toBe("c-cgx");
  });

  it("returns disambiguation when fuzzy match is ambiguous", () => {
    // "conver" matches both "Convergix" and "Convergent Group" via startsWith
    const result = resolveClientFromList(all, "Conver");
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error).toMatch(/Multiple clients match 'Conver'/);
      expect(result.error).toContain("Use --client <slug>");
      expect(result.available).toEqual(
        expect.arrayContaining(["Convergix (slug=convergix)", "Convergent Group (slug=convergent-group)"]),
      );
    }
  });

  it("returns not-found error on no match", () => {
    const result = resolveClientFromList(all, "Nope");
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.error).toBe("Client 'Nope' not found.");
      expect(result.available).toEqual(["AG1", "Convergix", "Convergent Group"]);
      // not-found returns plain client names (not "(slug=...)") since user
      // could match by name; the slug hint is only added on ambiguous-multi.
    }
  });
});

